head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > ondatadragstart]<br/>Drag 로 Body 영역의 데이터 이동을 시작할 때 발생합니다.",
    "validation" : [
        "이벤트는 dataDragSelect 속성에 의해 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - target1 에 dataDragSelect=true + useShiftKey=true 고정 (dataDragDrop* 미설정 -> dataDragSelect 활성, 상호배타)
//  - 셀 선택 Drag 시 ondatadragstart 는 발생하지 않음 (미발생 확인용)
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind1 !== 'undefined') {
        $p.data.remove("dlt_bind1");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] target1 에 dataDragSelect=true / useShiftKey=true (셀 선택 Drag 모드).\n[절차] target1 의 한 셀에서 다른 셀로 Drag 하여 영역 선택.\n[확인] 셀은 선택되지만 ondatadragstart 는 발생하지 않습니다(결과창 출력 없음)."', '', 'label1');

    // properties 고정 : dataDragSelect=true + useShiftKey=true (dataDragDrop* 미설정 -> dataDragSelect 활성 조건 충족)
    let properties = {
        dataList: "data:dlt_bind1",
        dataDragSelect: "true",
        useShiftKey: "true"
    };

    let cList = $c.gcm.createCList(properties);

    // 이벤트 핸들러 부착 : target1 에 ondatadragstart (미발생 확인용)
    let eList = $c.gcm.createEList(["ondatadragstart"], "target1");

    // dataList 생성 (기본 4행) + target1 생성 (기본 4컬럼)
    $c.gcm.createBasicDataList('', '', 'dlt_bind1');
    await $c.gcm.createBasicGridView(cList, eList, 'target1');
}



// ondatadragstart : dataDragSelect 모드에서는 발생하지 않아야 함 (@spec : dataDragSelect 에 의해 발생하지 않음)
//  - 정상 동작 시 호출되지 않으므로 결과창 출력이 없음
scwin.target1_ondatadragstart = function (rowIndex) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("ondatadragstart rowIndex : " + rowIndex);
};
